#include "Library/Synth/Core/Engines/Drums/DrumSounds.h"

namespace synth::drums {

namespace {

// kDrumSoundFrames, kDrumSounds and kDrumKits: generated by tools/audio/drum_sounds.py (see
// cmake/CardenzaSynthSourceLists.cmake), kept out of Git. Const, so the frames stay in flash.
#include "Library/Synth/Core/Engines/Drums/generated/DrumSoundData.inc"

}  // namespace

std::size_t SoundCount() { return sizeof(kDrumSounds) / sizeof(kDrumSounds[0]); }

const DrumSound& Sound(std::size_t index) { return kDrumSounds[index < SoundCount() ? index : 0]; }

const std::int16_t* SoundFrames(const DrumSound& sound)
{
  return sound.romPreset == kEmbedded ? kDrumSoundFrames + sound.offset : nullptr;
}

std::size_t KitCount() { return sizeof(kDrumKits) / sizeof(kDrumKits[0]); }

const DrumKit& Kit(std::size_t index) { return kDrumKits[index < KitCount() ? index : 0]; }

}  // namespace synth::drums
